extern "C" double clamp(double var, double min, double max) {
    return std::clamp(var, min, max);
}

extern "C" double next_color(double* color, double color_count) {
    if (*color + 1 < color_count) {
        *color += 1;
    } else {
        *color = 0;
    }
    return *color;
}

using namespace llvm;

int main(int argc, char** argv) {
    InitializeNativeTarget();
    InitializeNativeTargetAsmPrinter();
    InitializeNativeTargetAsmParser();

    LLVMContext context;
    SMDiagnostic error;


    auto module = std::make_unique<Module>("main_module", context);
    IRBuilder<> builder(context);

    // Define main function signature: int main()
    auto intType = Type::getInt32Ty(context);
    auto doubleType = Type::getDoubleTy(context);
    auto arrayType = ArrayType::get(doubleType, 8);
    auto mainFuncType = FunctionType::get(intType, false);
    auto mainFunction = Function::Create(mainFuncType, Function::ExternalLinkage, "main", module.get());

    // Entry block
    auto entryBlock = BasicBlock::Create(context, "entry", mainFunction);
    builder.SetInsertPoint(entryBlock);

    // Call simInit
    auto simInitFuncType = FunctionType::get(Type::getVoidTy(context), false);
    auto simInitFunc = Function::Create(simInitFuncType, Function::ExternalLinkage, "simInit", module.get());
    builder.CreateCall(simInitFunc);

    // Allocate variables
    auto windowWidth = builder.CreateAlloca(doubleType, nullptr, "WINDOW_WIDTH");
    builder.CreateStore(ConstantFP::get(context, APFloat(1920.0)), windowWidth);

    auto windowHeight = builder.CreateAlloca(doubleType, nullptr, "WINDOW_HEIGHT");
    builder.CreateStore(ConstantFP::get(context, APFloat(1080.0)), windowHeight);

    auto imageWidth = builder.CreateAlloca(doubleType, nullptr, "image_width");
    builder.CreateStore(ConstantFP::get(context, APFloat(500.0)), imageWidth);

    auto imageHeight = builder.CreateAlloca(doubleType, nullptr, "image_height");
    builder.CreateStore(ConstantFP::get(context, APFloat(299.0)), imageHeight);

    auto imageColor = builder.CreateAlloca(doubleType, nullptr, "image_color");
    builder.CreateStore(ConstantFP::get(context, APFloat(255.0)), imageColor);

    auto image = builder.CreateAlloca(ArrayType::get(doubleType, 149500), nullptr, "image");

    // Call init_image
    auto initImageFuncType = FunctionType::get(Type::getVoidTy(context), {PointerType::getUnqual(doubleType), doubleType, doubleType, doubleType}, false);
    auto initImageFunc = Function::Create(initImageFuncType, Function::ExternalLinkage, "init_image", module.get());
    auto imagePtr = builder.CreateGEP(ArrayType::get(doubleType, 149500), image, {builder.getInt32(0), builder.getInt32(0)});
    builder.CreateCall(initImageFunc, {imagePtr, builder.CreateLoad(doubleType, imageWidth), builder.CreateLoad(doubleType, imageHeight), builder.CreateLoad(doubleType, imageColor)});

    // Allocate and initialize colors array
    auto colors = builder.CreateAlloca(arrayType, nullptr, "colors");
    
    std::vector<Constant*> colorValues =  { 
        ConstantFP::get(context, APFloat((double)0x000000FF)),
        ConstantFP::get(context, APFloat((double)0x0000FFFF)),
        ConstantFP::get(context, APFloat((double)0x0000FF00)),
        ConstantFP::get(context, APFloat((double)0x00FF00FF)),
        ConstantFP::get(context, APFloat((double)0x00FF7F00)),
        ConstantFP::get(context, APFloat((double)0x007F00FF)),
        ConstantFP::get(context, APFloat((double)0x00FF0000)),          
        ConstantFP::get(context, APFloat((double)0x00FFFF00)) 
    };  
    for (int i = 0; i < 8; ++i) {
      auto elementPtr = builder.CreateGEP(arrayType, colors, {builder.getInt32(0), builder.getInt32(i)});
      builder.CreateStore(colorValues[i], elementPtr);
    }

    //Start of new block:
    auto colorCount = builder.CreateAlloca(doubleType, nullptr, "color_count");
    builder.CreateStore(ConstantFP::get(context, APFloat(8.0)), colorCount);
    
    auto currentColor = builder.CreateAlloca(doubleType, nullptr, "current_color");
    builder.CreateStore(ConstantFP::get(context, APFloat(0.0)), currentColor);
    
    auto imageX = builder.CreateAlloca(doubleType, nullptr, "image_x");
    builder.CreateStore(ConstantFP::get(context, APFloat(600.0)), imageX);
    
     auto imageY = builder.CreateAlloca(doubleType, nullptr, "image_y");
    builder.CreateStore(ConstantFP::get(context, APFloat(600.0)), imageY);
    
     auto speedX = builder.CreateAlloca(doubleType, nullptr, "speed_x");
     builder.CreateStore(ConstantFP::get(context, APFloat(5.0)), speedX);
     
     auto speedY = builder.CreateAlloca(doubleType, nullptr, "speed_y");
     builder.CreateStore(ConstantFP::get(context, APFloat(5.0)), speedY);
     
     auto dx = builder.CreateAlloca(doubleType, nullptr, "dx");
     builder.CreateStore(ConstantFP::get(context, APFloat(1.0)), dx);
     
     auto dy = builder.CreateAlloca(doubleType, nullptr, "dy");
     builder.CreateStore(ConstantFP::get(context, APFloat(1.0)), dy);
     
     auto i = builder.CreateAlloca(doubleType, nullptr, "i");
    auto j = builder.CreateAlloca(doubleType, nullptr, "j");
    auto hasColor = builder.CreateAlloca(doubleType, nullptr, "has_color");
    auto x = builder.CreateAlloca(doubleType, nullptr, "x");
    auto y = builder.CreateAlloca(doubleType, nullptr, "y");
    
    auto whileTest1BB = BasicBlock::Create(context, "while_test1", mainFunction);
    builder.CreateBr(whileTest1BB);

    // while_test1 block
    builder.SetInsertPoint(whileTest1BB);
    auto whileLoop2BB = BasicBlock::Create(context, "while_loop2", mainFunction);
    auto whileEnd3BB = BasicBlock::Create(context, "while_end3", mainFunction);
    builder.CreateCondBr(ConstantInt::get(Type::getInt1Ty(context), 1), whileLoop2BB, whileEnd3BB);

    // while_loop2 block
    builder.SetInsertPoint(whileLoop2BB);
    auto imageXLoad1 = builder.CreateLoad(doubleType, imageX);
    auto fcmp1 = builder.CreateFCmpUGT(ConstantFP::get(context, APFloat(0.0)), imageXLoad1);
    auto imageXLoad2 = builder.CreateLoad(doubleType, imageX);
    auto imageWidthLoad = builder.CreateLoad(doubleType, imageWidth);
    auto fadd = builder.CreateFAdd(imageXLoad2, imageWidthLoad);
    auto windowWidthLoad = builder.CreateLoad(doubleType, windowWidth);
    auto fcmp2 = builder.CreateFCmpUGE(fadd, windowWidthLoad);
    auto orOp = builder.CreateOr(fcmp1, fcmp2);
    
    auto ifTrue4BB = BasicBlock::Create(context, "if_true_4", mainFunction);
    auto ifFalse5BB = BasicBlock::Create(context, "if_false_5", mainFunction);
    builder.CreateCondBr(orOp, ifTrue4BB, ifFalse5BB);

    // while_end3 block
    builder.SetInsertPoint(whileEnd3BB);
    auto simExitFuncType = FunctionType::get(Type::getVoidTy(context), false);
    auto simExitFunc = Function::Create(simExitFuncType, Function::ExternalLinkage, "simExit", module.get());
    builder.CreateCall(simExitFunc);
    builder.CreateRet(ConstantFP::get(context, APFloat(0.0)));

    // if_true_4 block
    builder.SetInsertPoint(ifTrue4BB);
     auto windowWidthLoad2 = builder.CreateLoad(doubleType, windowWidth);
     auto imageWidthLoad2 = builder.CreateLoad(doubleType, imageWidth);
     auto fsub1 = builder.CreateFSub(windowWidthLoad2, imageWidthLoad2);
     auto fsub2 = builder.CreateFSub(fsub1, ConstantFP::get(context, APFloat(1.0)));
     auto imageXLoad3 = builder.CreateLoad(doubleType, imageX);
    
    auto clampFuncType = FunctionType::get(doubleType, {doubleType, doubleType, doubleType}, false);
    auto clampFunc = Function::Create(clampFuncType, Function::ExternalLinkage, "clamp", module.get());
    auto clampCall = builder.CreateCall(clampFunc, {imageXLoad3, ConstantFP::get(context, APFloat(0.0)), fsub2});
    builder.CreateStore(clampCall, imageX);
    
    auto speedXLoad = builder.CreateLoad(doubleType, speedX);
    auto fsub3 = builder.CreateFSub(ConstantFP::get(context, APFloat(0.0)), speedXLoad);
    builder.CreateStore(fsub3, speedX);

    auto colorCountLoad = builder.CreateLoad(doubleType, colorCount);
    auto nextColorFuncType = FunctionType::get(doubleType, {PointerType::getUnqual(doubleType), doubleType}, false);
    auto nextColorFunc = Function::Create(nextColorFuncType, Function::ExternalLinkage, "next_color", module.get());
    auto nextColorCall = builder.CreateCall(nextColorFunc, {currentColor, colorCountLoad});
    auto fptoui = builder.CreateFPToUI(nextColorCall, Type::getInt32Ty(context));
    auto gep = builder.CreateGEP(arrayType, colors, {builder.getInt32(0), fptoui});
    auto colorLoad = builder.CreateLoad(doubleType, gep);
    builder.CreateStore(colorLoad, imageColor);

    auto ifEnd6BB = BasicBlock::Create(context, "if_end_6", mainFunction);
    builder.CreateBr(ifEnd6BB);

    // if_false_5 block
    builder.SetInsertPoint(ifFalse5BB);
    builder.CreateBr(ifEnd6BB);

    // if_end_6 block
     builder.SetInsertPoint(ifEnd6BB);
    auto imageYLoad1 = builder.CreateLoad(doubleType, imageY);
    auto fcmp3 = builder.CreateFCmpUGT(ConstantFP::get(context, APFloat(0.0)), imageYLoad1);
    auto imageYLoad2 = builder.CreateLoad(doubleType, imageY);
    auto imageHeightLoad = builder.CreateLoad(doubleType, imageHeight);
    auto fadd2 = builder.CreateFAdd(imageYLoad2, imageHeightLoad);
    auto windowHeightLoad = builder.CreateLoad(doubleType, windowHeight);
    auto fcmp4 = builder.CreateFCmpUGE(fadd2, windowHeightLoad);
    auto orOp2 = builder.CreateOr(fcmp3, fcmp4);

    auto ifTrue7BB = BasicBlock::Create(context, "if_true_7", mainFunction);
    auto ifFalse8BB = BasicBlock::Create(context, "if_false_8", mainFunction);
    builder.CreateCondBr(orOp2, ifTrue7BB, ifFalse8BB); 

    // if_true_7 block
    builder.SetInsertPoint(ifTrue7BB);
    auto windowHeightLoad3 = builder.CreateLoad(doubleType, windowHeight);
     auto imageHeightLoad2 = builder.CreateLoad(doubleType, imageHeight);
     auto fsub4 = builder.CreateFSub(windowHeightLoad3, imageHeightLoad2);
     auto fsub5 = builder.CreateFSub(fsub4, ConstantFP::get(context, APFloat(1.0)));
     auto imageYLoad3 = builder.CreateLoad(doubleType, imageY);

    auto clampCall2 = builder.CreateCall(clampFunc, {imageYLoad3, ConstantFP::get(context, APFloat(0.0)), fsub5});
    builder.CreateStore(clampCall2, imageY);
     
    auto speedYLoad = builder.CreateLoad(doubleType, speedY);
    auto fsub6 = builder.CreateFSub(ConstantFP::get(context, APFloat(0.0)), speedYLoad);
    builder.CreateStore(fsub6, speedY);

    auto colorCountLoad2 = builder.CreateLoad(doubleType, colorCount);
    auto nextColorCall2 = builder.CreateCall(nextColorFunc, {currentColor, colorCountLoad2});
    auto fptoui2 = builder.CreateFPToUI(nextColorCall2, Type::getInt32Ty(context));
    auto gep2 = builder.CreateGEP(arrayType, colors, {builder.getInt32(0), fptoui2});
    auto colorLoad2 = builder.CreateLoad(doubleType, gep2);
    builder.CreateStore(colorLoad2, imageColor);

    auto ifEnd9BB = BasicBlock::Create(context, "if_end_9", mainFunction);
    builder.CreateBr(ifEnd9BB);
    
    // if_false_8 block
    builder.SetInsertPoint(ifFalse8BB);
    builder.CreateBr(ifEnd9BB);

    // if_end_9 block
     builder.SetInsertPoint(ifEnd9BB);
    auto simClearWindowFuncType = FunctionType::get(Type::getVoidTy(context), false);
    auto simClearWindowFunc = Function::Create(simClearWindowFuncType, Function::ExternalLinkage, "simClearWindow", module.get());
    builder.CreateCall(simClearWindowFunc);

    builder.CreateStore(ConstantFP::get(context, APFloat(0.0)), i);

    auto whileTest10BB = BasicBlock::Create(context, "while_test10", mainFunction);
    builder.CreateBr(whileTest10BB);

    //while_test10 block
     builder.SetInsertPoint(whileTest10BB);
    auto iLoad = builder.CreateLoad(doubleType, i);
    auto imageWidthLoad3 = builder.CreateLoad(doubleType, imageWidth);
    auto fcmp5 = builder.CreateFCmpULT(iLoad, imageWidthLoad3);
    
    auto whileLoop11BB = BasicBlock::Create(context, "while_loop11", mainFunction);
    auto whileEnd12BB = BasicBlock::Create(context, "while_end12", mainFunction);
    builder.CreateCondBr(fcmp5, whileLoop11BB, whileEnd12BB);

    // while_loop11 block
     builder.SetInsertPoint(whileLoop11BB);
    builder.CreateStore(ConstantFP::get(context, APFloat(0.0)), j);
    
    auto whileTest13BB = BasicBlock::Create(context, "while_test13", mainFunction);
    builder.CreateBr(whileTest13BB);

    // while_end12 block
     builder.SetInsertPoint(whileEnd12BB);
    auto simFlushFuncType = FunctionType::get(Type::getVoidTy(context), false);
    auto simFlushFunc = Function::Create(simFlushFuncType, Function::ExternalLinkage, "simFlush", module.get());
    builder.CreateCall(simFlushFunc);
    
    auto imageXLoad4 = builder.CreateLoad(doubleType, imageX);
    auto speedXLoad2 = builder.CreateLoad(doubleType, speedX);
    auto dxLoad = builder.CreateLoad(doubleType, dx);
    auto fmul1 = builder.CreateFMul(speedXLoad2, dxLoad);
    auto fadd3 = builder.CreateFAdd(imageXLoad4, fmul1);
    builder.CreateStore(fadd3, imageX);

    auto imageYLoad4 = builder.CreateLoad(doubleType, imageY);
    auto speedYLoad2 = builder.CreateLoad(doubleType, speedY);
    auto dyLoad = builder.CreateLoad(doubleType, dy);
    auto fmul2 = builder.CreateFMul(speedYLoad2, dyLoad);
    auto fadd4 = builder.CreateFAdd(imageYLoad4, fmul2);
    builder.CreateStore(fadd4, imageY);
    builder.CreateBr(whileTest1BB);

    //while_test13 block
     builder.SetInsertPoint(whileTest13BB);
    auto jLoad = builder.CreateLoad(doubleType, j);
    auto imageHeightLoad3 = builder.CreateLoad(doubleType, imageHeight);
    auto fcmp6 = builder.CreateFCmpULT(jLoad, imageHeightLoad3);

    auto whileLoop14BB = BasicBlock::Create(context, "while_loop14", mainFunction);
    auto whileEnd15BB = BasicBlock::Create(context, "while_end15", mainFunction);
    builder.CreateCondBr(fcmp6, whileLoop14BB, whileEnd15BB);

   //while_loop14 block
     builder.SetInsertPoint(whileLoop14BB);
    auto jLoad2 = builder.CreateLoad(doubleType, j);
     auto imageWidthLoad4 = builder.CreateLoad(doubleType, imageWidth);
    auto fmul3 = builder.CreateFMul(jLoad2, imageWidthLoad4);
    auto iLoad2 = builder.CreateLoad(doubleType, i);
     auto fadd5 = builder.CreateFAdd(fmul3, iLoad2);
    auto fptoui3 = builder.CreateFPToUI(fadd5, Type::getInt32Ty(context));
    auto gep3 = builder.CreateGEP(ArrayType::get(doubleType, 149500), image, {builder.getInt32(0), fptoui3});
    auto imageLoad = builder.CreateLoad(doubleType, gep3);
    builder.CreateStore(imageLoad, hasColor);

    auto imageXLoad5 = builder.CreateLoad(doubleType, imageX);
    auto iLoad3 = builder.CreateLoad(doubleType, i);
    auto fadd6 = builder.CreateFAdd(imageXLoad5, iLoad3);
     builder.CreateStore(fadd6, x);

    auto imageYLoad5 = builder.CreateLoad(doubleType, imageY);
    auto jLoad3 = builder.CreateLoad(doubleType, j);
    auto fadd7 = builder.CreateFAdd(imageYLoad5, jLoad3);
     builder.CreateStore(fadd7, y);
    
    auto hasColorLoad = builder.CreateLoad(doubleType, hasColor);
    auto fcmp7 = builder.CreateFCmpUNE(hasColorLoad, ConstantFP::get(context, APFloat(0.0)));

    auto ifTrue16BB = BasicBlock::Create(context, "if_true_16", mainFunction);
    auto ifFalse17BB = BasicBlock::Create(context, "if_false_17", mainFunction);
    builder.CreateCondBr(fcmp7, ifTrue16BB, ifFalse17BB);

    // while_end15 block
     builder.SetInsertPoint(whileEnd15BB);
    auto iLoad4 = builder.CreateLoad(doubleType, i);
    auto fadd8 = builder.CreateFAdd(iLoad4, ConstantFP::get(context, APFloat(1.0)));
    builder.CreateStore(fadd8, i);
     builder.CreateBr(whileTest10BB);

     //if_true_16 block
     builder.SetInsertPoint(ifTrue16BB);
    auto imageColorLoad = builder.CreateLoad(doubleType, imageColor);
    auto fptosi1 = builder.CreateFPToSI(imageColorLoad, Type::getInt32Ty(context));

    auto yLoad = builder.CreateLoad(doubleType, y);
     auto fptosi2 = builder.CreateFPToSI(yLoad, Type::getInt32Ty(context));
     
    auto xLoad = builder.CreateLoad(doubleType, x);
     auto fptosi3 = builder.CreateFPToSI(xLoad, Type::getInt32Ty(context));

    auto simPutPixelFuncType = FunctionType::get(Type::getVoidTy(context), {Type::getInt32Ty(context), Type::getInt32Ty(context), Type::getInt32Ty(context)}, false);
    auto simPutPixelFunc = Function::Create(simPutPixelFuncType, Function::ExternalLinkage, "simPutPixel", module.get());
    builder.CreateCall(simPutPixelFunc, {fptosi3, fptosi2, fptosi1});
    
     auto ifEnd18BB = BasicBlock::Create(context, "if_end_18", mainFunction);
     builder.CreateBr(ifEnd18BB);

    //if_false_17 block
    builder.SetInsertPoint(ifFalse17BB);
    builder.CreateBr(ifEnd18BB);

     //if_end_18 block
     builder.SetInsertPoint(ifEnd18BB);
    auto jLoad4 = builder.CreateLoad(doubleType, j);
    auto fadd9 = builder.CreateFAdd(jLoad4, ConstantFP::get(context, APFloat(1.0)));
    builder.CreateStore(fadd9, j);
     builder.CreateBr(whileTest13BB);

    //  Add a return instruction to the main function to make it valid
    builder.CreateRet(ConstantInt::get(intType, 0));

    // Print the IR
    module->print(llvm::outs(), nullptr);

    std::string errStr;
    ExecutionEngine* engine = EngineBuilder(std::move(module))
                                  .setErrorStr(&errStr)
                                  .setMCJITMemoryManager(std::make_unique<SectionMemoryManager>())
                                  .create();

    if (!engine) {
        std::cerr << "Failed to create ExecutionEngine: " << errStr << std::endl;
        return 1;
    }

    std::cout << "Create ExecutionEngine\n";
    engine->addGlobalMapping("simInit", reinterpret_cast<uint64_t>(&simInit));
    engine->addGlobalMapping("simExit", reinterpret_cast<uint64_t>(&simExit));
    engine->addGlobalMapping("simFlush", reinterpret_cast<uint64_t>(&simFlush));
    engine->addGlobalMapping("simClearWindow", reinterpret_cast<uint64_t>(&simClearWindow));
    engine->addGlobalMapping("simPutPixel", reinterpret_cast<uint64_t>(&simPutPixel));
    engine->addGlobalMapping("init_image", reinterpret_cast<uint64_t>(&init_image));
    engine->addGlobalMapping("clamp", reinterpret_cast<uint64_t>(&clamp));
    engine->addGlobalMapping("next_color", reinterpret_cast<uint64_t>(&next_color));

    std::vector<GenericValue> args;
    std::cout << "Run main\n";
    GenericValue result = engine->runFunction(mainFunction, args);
    llvm::outs() << "Result from 'main': " << result.IntVal << "\n";
    return 0;
}
